def quote_ladder(mid, levels=3, step=0.05, size=100):
    orders = []
    for k in range(1, levels + 1):
        orders.append(('bid', round(mid - k * step, 2), k * size))
    for k in range(1, levels + 1):
        orders.append(('ask', round(mid + k * step, 2), k * size))
    return orders

